package com.universe.user.dto.response; import com.universe.user.entity.User; import lombok.AllArgsConstructor; import lombok.Getter; @Getter @AllArgsConstructor public class UserResponse { private Long userId; private String email; private String name; private String nickname; private String department; private Long schoolId; private String schoolName; private boolean schoolVerified; private String role; private String accountStatus; private int trustScore; public static UserResponse from(User u){ return new UserResponse(u.getId(),u.getEmail(),u.getName(),u.getNickname(),u.getDepartment(),u.getSchool()==null?null:u.getSchool().getId(),u.getSchool()==null?null:u.getSchool().getSchoolName(),Boolean.TRUE.equals(u.getSchoolVerified()),u.getRole().name(),u.getAccountStatus().name(),u.getTrustScore()); } }
